def run(fn,npar,n=60):
    best=None
    for _ in range(n):
        p0=rng.normal(0,1,npar)
        try:
            r=least_squares(lambda p: np.nan_to_num(fn(p)-y,nan=1e3,posinf=1e3,neginf=-1e3), p0, max_nfev=2000)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
